"""One definition of "this generated file leaks a local path".

A published artefact that names `D:\\PODS Project\\...` or `/Users/<name>/...`
discloses the machine layout and the operator's account, and it cannot be
reproduced on any other checkout. The scan here is shared by the Phase 0 audit,
the CI guard and the one-shot sanitiser so all three agree on what counts.
"""
import re
from pathlib import Path

from src import config

# Windows drive roots (escaped or not) and POSIX home directories.
LEAK = re.compile(r'[A-Z]:\\\\|[A-Z]:\\|[A-Z]:/|/Users/|/home/[a-z]')
# Generated and published trees. Source code may legitimately mention a path.
SCAN_ROOTS = ('results', 'data', 'webapp/public', 'docs', 'reports', 'paper')
TEXT_SUFFIXES = {'.json', '.csv', '.md', '.txt', '.tex'}
# The spec's own Part B quotes the leak it is reporting, and the audit quotes
# Part B. Exempting them by path keeps the evidence readable without blinding
# the scan to anything that is actually generated by a writer we control.
EXEMPT = {
    'docs/MASTER_SPEC.md',
    'docs/AUDIT_CONFIRMATION.md',
    'docs/PROGRESS.md',
    'results/audit_confirmation.json',
}


def scan(roots=SCAN_ROOTS, root=None):
    """Return the repository-relative paths of text artefacts that leak a path."""
    base_dir = Path(root or config.PROJECT_ROOT)
    hits = []
    for name in roots:
        base = base_dir / name
        if not base.exists():
            continue
        for path in sorted(base.rglob('*')):
            if not path.is_file() or path.suffix.lower() not in TEXT_SUFFIXES:
                continue
            relative = path.relative_to(base_dir).as_posix()
            if relative in EXEMPT:
                continue
            try:
                text = path.read_text(encoding='utf-8')
            except (UnicodeDecodeError, OSError):
                continue
            if LEAK.search(text):
                hits.append(relative)
    return hits
